/// <summary>
/// WolfA 16.04.21
/// </summary>
[DataContractAttribute, SysOperationContractProcessing(classStr(NDXUSCImportUIBuilder))]
class NDXUSCImportContract
{
    TaxVATNumTable taxVATNumTable;
    VATNum vatNum;
    NoYes all;

}

Method.Source:
[DataMemberAttribute('VATNum'), SysOperationLabelAttribute("@SYS8946"), SysOperationDisplayOrder('1')]
public VATNum parmVatNum(VATNum _vatNum = VATNum)
{
    vatNum = _vatNum;
    return vatNum;
}

[DataMemberAttribute("All"), SysOperationLabelAttribute("@SYS114513"), SysOperationHelpText("@NDX:NDXCheckAllRecords_Help"), SysOperationDisplayOrder('2')]
public NoYes parmAll(NoYes _all= all)
{
    all= _all;
    return all;
}

[DataMemberAttribute('TaxVATNumTable')]
public TaxVATNumTable parmTaxVATNumTable(TaxVATNumTable _taxVATNumTable = taxVATNumTable)
{
    taxVATNumTable = _taxVATNumTable;
    this.vatNum = taxVATNumTable.VATNum;
    return taxVATNumTable;
}
